#!/usr/bin/env python3

# Fixes .rc files generated by Microsoft Developer Studio so that windres will
# correctly interpret them. To ensure correct paths to files, execute this script
# from the same place you will execute windres.

import platform
import re
import sys

infile = None
outfile = None

# Process command line arguments
args = sys.argv[1:]
i = 0
while i < len(args):
	# Output file
	if re.match(r'^-o', args[i], re.I):
		if re.match(r'^-o$', args[i], re.I):
			i += 1
			if i < len(args):
				outfile = args[i]
		else:
			outfile = args[i][2:]
	else:
		# Input file
		infile = args[i]
	i += 1

if not (infile and outfile):
	sys.exit("Usage: %s <input file> -o <output file>\n" % sys.argv[0])

print("Converting %s for use with windres..." % infile)

# llvm-rc doesn't support multiplication, precompute constant products (outside of strings)
def precompute_products(line):
	parts = re.split(r'("(?:[^"]|"")*")', line)
	for n, part in enumerate(parts):
		if part.startswith('"'):
			continue
		while True:
			part, count = re.subn(r'(\d+)\s*\*\s*(\d+)', lambda m: str(int(m.group(1)) * int(m.group(2))), part, count=1, flags=re.A)
			if count == 0:
				break
		parts[n] = part
	return ''.join(parts)


with open(infile, encoding='latin-1') as fin, open(outfile, 'w', encoding='latin-1') as fout:
	# first define missing constants and include needed files
	fout.write("""// This file is a windres compatible version of %s
// It was fixed by %s (python %s)

// afxres.h cannot be redistributed, so define constants and include files needed here
#ifndef _MSC_VER

 #ifndef RC_INVOKED
  #define RC_INVOKED
 #endif

 #include <windows.h>
 #include <richedit.h>

 #ifndef IDC_STATIC
  #define IDC_STATIC (-1)
 #endif

#endif

""" % (infile, sys.argv[0], platform.python_version()))

	for line in fin:
		line = line.rstrip('\n')
		if re.match(r'^#include "afxres.h"', line):
			fout.write("#ifdef _MSC_VER\n")
			fout.write(line + "\n")
			fout.write("#endif\n")
		else:
			# add NOT WS_POPUP to all windows with WS_CHILD specified
			line = re.sub(r'(?<!NOT\s)(WS_CHILD)', r'\1 | NOT WS_POPUP', line, count=1, flags=re.A)

			line = precompute_products(line)

			# Fix FONT statements (remove rubbish after font name)
			m = re.match(r'(^FONT\s+\w+,\s*".*")', line, re.A)
			if m:
				line = m.group(1)

			fout.write(line + "\n")
